import './ProgressBar.css';

interface Props {
  value: number;
  variant: 'run' | 'stamina';
}

const ProgressBar = ({ value, variant }: Props) => {
  const clamped = Math.min(Math.max(value, 0), 1);

  let colorClass: string;
  if (variant === 'run') {
    colorClass = 'progress-fill--run';
  } else if (clamped > 0.6) {
    colorClass = 'progress-fill--green';
  } else if (clamped > 0.3) {
    colorClass = 'progress-fill--amber';
  } else {
    colorClass = 'progress-fill--red';
  }

  return (
    <div className="progress-track">
      <div className={`progress-fill ${colorClass}`} style={{ width: `${clamped * 100}%` }} />
    </div>
  );
};

export default ProgressBar;
