interface Props {
  bases: boolean[];
}

const BasesBug = ({ bases }: Props) => (
  <div className="bases-diamond">
    <div className={`bases-diamond__base bases-diamond__base--second${bases[1] ? ' bases-diamond__base--on' : ''}`} />
    <div className={`bases-diamond__base bases-diamond__base--third${bases[2] ? ' bases-diamond__base--on' : ''}`} />
    <div className={`bases-diamond__base bases-diamond__base--first${bases[0] ? ' bases-diamond__base--on' : ''}`} />
  </div>
);

export default BasesBug;
