import './PipGroup.css';

interface Props {
  label: string;
  count: number;
  max: number;
  variant: 'ball' | 'strike' | 'out';
}

const PipGroup = ({ label, count, max, variant }: Props) => (
  <div className="pip-group">
    <span className="pip-group__label">{label}</span>
    <div className="pip-group__pips">
      {Array.from({ length: max }, (_, i) => (
        <div key={i} className={`pip pip--${variant}${i < count ? ' pip--on' : ''}`} />
      ))}
    </div>
  </div>
);

export default PipGroup;
