import { useEffect, useRef, useState } from "react";
import { PlayerArchetype } from "../../types/playerArchetype";
import { AVERAGE_JOE } from "../../data/playerArchetypes";
import {
  ARCHETYPE_VISUAL,
  CARD_NAME_TO_GEM,
  CARD_TYPE_GEMS,
  GemKey,
} from "../../data/archetypeMetadata";
import PlayerCard from "../PlayerCard/PlayerCard";
import "./RecruitScreen.css";

interface Props {
  recruits: PlayerArchetype[];
  roster: PlayerArchetype[];
  onConfirm: (slot: number, recruit: PlayerArchetype) => void;
}

const CARD_W = 175;
const CARD_GAP = 12;
const SLOT_W = CARD_W + CARD_GAP;

function GemRow({ cards }: { cards: string[] }) {
  const gems = cards
    .map((c) => CARD_NAME_TO_GEM[c] as GemKey | undefined)
    .filter(Boolean) as GemKey[];
  return (
    <div className="recruit-gem-row">
      {gems.slice(0, 5).map((key, i) => {
        const gem = CARD_TYPE_GEMS[key];
        return (
          <div
            key={i}
            className="recruit-gem"
            style={{ background: `linear-gradient(160deg, ${gem.c} 0%, ${gem.d} 100%)` }}
          >
            <span>{gem.L}</span>
          </div>
        );
      })}
    </div>
  );
}

const RecruitScreen = ({ recruits, roster, onConfirm }: Props) => {
  const [selectedRecruit, setSelectedRecruit] = useState<PlayerArchetype | null>(null);
  const [activeIndex, setActiveIndex] = useState(0);
  const [selectedSlot, setSelectedSlot] = useState<number | null>(null);
  const [containerWidth, setContainerWidth] = useState(375);
  const carouselRef = useRef<HTMLDivElement>(null);
  const dragStartX = useRef<number | null>(null);

  useEffect(() => {
    const el = carouselRef.current;
    if (!el) return;
    const obs = new ResizeObserver((entries) => {
      const w = entries[0].contentRect.width;
      if (w > 0) setContainerWidth(w);
    });
    obs.observe(el);
    return () => obs.disconnect();
  }, []);

  const trackX = containerWidth / 2 - activeIndex * SLOT_W - CARD_W / 2;

  const handlePointerDown = (e: React.PointerEvent) => {
    dragStartX.current = e.clientX;
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (dragStartX.current === null) return;
    const dx = e.clientX - dragStartX.current;
    dragStartX.current = null;
    if (dx < -40 && activeIndex < recruits.length - 1) setActiveIndex((i) => i + 1);
    else if (dx > 40 && activeIndex > 0) setActiveIndex((i) => i - 1);
  };

  // ── Step 1: Pick ────────────────────────────────────────────────────────────
  if (!selectedRecruit) {
    return (
      <div className="bb-screen recruit-screen">
        <div className="recruit-header">
          <div className="recruit-eyebrow">◆ BOSS DEFEATED!</div>
          <div className="recruit-title">DRAFT A PLAYER</div>
          <div className="recruit-subtitle">Choose one to join your lineup</div>
        </div>

        <div
          className="recruit-carousel"
          ref={carouselRef}
          onPointerDown={handlePointerDown}
          onPointerUp={handlePointerUp}
          onPointerCancel={() => { dragStartX.current = null; }}
        >
          <div
            className="recruit-carousel__track"
            style={{ transform: `translateX(${trackX}px)` }}
          >
            {recruits.map((recruit, i) => {
              const isCenter = i === activeIndex;
              return (
                <div
                  key={i}
                  className={`recruit-carousel__slot${isCenter ? " recruit-carousel__slot--center" : " recruit-carousel__slot--peek"}`}
                  onClick={() => { if (!isCenter) setActiveIndex(i); }}
                >
                  <PlayerCard archetype={recruit} />
                </div>
              );
            })}
          </div>
        </div>

        <div className="recruit-dots">
          {recruits.map((_, i) => (
            <div
              key={i}
              className={`recruit-dot${i === activeIndex ? " recruit-dot--active" : ""}`}
              onClick={() => setActiveIndex(i)}
            />
          ))}
        </div>

        <div className="recruit-ctas">
          <button
            className="bb-btn bb-btn--primary"
            onClick={() => {
              setSelectedRecruit(recruits[activeIndex]);
              setSelectedSlot(null);
            }}
          >
            ◆ Draft {recruits[activeIndex].name}
          </button>
          <button className="bb-btn bb-btn--ghost">← Skip Recruit</button>
        </div>
      </div>
    );
  }

  // ── Step 2: Place ───────────────────────────────────────────────────────────
  const visual = ARCHETYPE_VISUAL[selectedRecruit.id];

  return (
    <div className="bb-screen recruit-screen recruit-screen--place">
      <div className="recruit-place-header">
        <button
          className="bb-btn bb-btn--ghost recruit-back-btn"
          onClick={() => {
            setSelectedRecruit(null);
            setSelectedSlot(null);
          }}
        >
          ← Back
        </button>
        <div className="recruit-place-title">
          PLACE: {selectedRecruit.name.toUpperCase()}
        </div>
        <div className="recruit-subtitle">Select an Average Joe slot to replace</div>
      </div>

      <div className="recruit-mini-preview">
        <div
          className="recruit-mini-card"
          style={{ borderColor: visual?.typeColor ?? "#D4A820" }}
        >
          {visual && (
            <>
              <img src={visual.backdrop} className="recruit-mini-card__bg" alt="" />
              <img
                src={visual.sprite}
                className="recruit-mini-card__sprite"
                alt={selectedRecruit.name}
              />
            </>
          )}
        </div>
        <div className="recruit-mini-info">
          <div className="recruit-mini-name">{selectedRecruit.name}</div>
          <div className="recruit-mini-type">Archetype</div>
          <GemRow cards={selectedRecruit.cards} />
        </div>
      </div>

      <div className="recruit-roster">
        {roster.map((player, i) => {
          const isReplaceable = player.id === AVERAGE_JOE.id;
          const isSelected = selectedSlot === i;
          return (
            <button
              key={i}
              className={`recruit-slot${isReplaceable ? " recruit-slot--replaceable" : " recruit-slot--locked"}${isSelected ? " recruit-slot--selected" : ""}`}
              onClick={() => {
                if (isReplaceable) setSelectedSlot(isSelected ? null : i);
              }}
              disabled={!isReplaceable}
            >
              <span className="recruit-slot__label">BAT {i + 1}</span>
              <div className="recruit-slot__body">
                <div className="recruit-slot__name">{player.name}</div>
                <GemRow cards={player.cards} />
              </div>
              {isReplaceable && (
                <span className={`recruit-slot__badge${isSelected ? " recruit-slot__badge--replace" : ""}`}>
                  {isSelected ? "← REPLACE" : "REPLACEABLE"}
                </span>
              )}
            </button>
          );
        })}
      </div>

      <div className="recruit-confirm-wrap">
        <button
          className="bb-btn bb-btn--primary"
          disabled={selectedSlot === null}
          onClick={() => {
            if (selectedSlot !== null) onConfirm(selectedSlot, selectedRecruit);
          }}
        >
          Confirm Placement
        </button>
      </div>
    </div>
  );
};

export default RecruitScreen;
