import { PlayerArchetype } from '../../types/playerArchetype';
import {
  ARCHETYPE_VISUAL,
  CARD_NAME_TO_GEM,
  CARD_TYPE_GEMS,
  GemKey,
} from '../../data/archetypeMetadata';
import './PlayerCard.css';

interface Props {
  archetype: PlayerArchetype;
  slotLabel?: string;
  gemSize?: number;
}

function Gem({ gemKey, size }: { gemKey: GemKey; size: number }) {
  const gem = CARD_TYPE_GEMS[gemKey];
  return (
    <div
      className="player-card-gem"
      style={{
        width: size,
        height: size,
        background: `linear-gradient(160deg, ${gem.c} 0%, ${gem.d} 100%)`,
      }}
      title={gemKey}
    >
      <span style={{ fontSize: size * 0.38 }}>{gem.L}</span>
    </div>
  );
}

const PlayerCard = ({ archetype, slotLabel, gemSize = 16 }: Props) => {
  const visual = ARCHETYPE_VISUAL[archetype.id];

  if (!visual) return null;

  const gems = archetype.cards.map(
    (card) => CARD_NAME_TO_GEM[card] as GemKey | undefined
  );

  return (
    <div className="player-card">
      {slotLabel && (
        <div className="player-card__header">{slotLabel}</div>
      )}

      <div
        className="player-card__art"
        style={{ background: visual.typeDeep }}
      >
        <img
          src={visual.backdrop}
          className="player-card__backdrop"
          alt=""
        />
        <div
          className="player-card__tint"
          style={{ background: visual.typeColor }}
        />
        <div
          className="player-card__glow"
          style={{
            background: `radial-gradient(95% 70% at 50% 0%, ${visual.typeGlow}55 0%, transparent 60%)`,
          }}
        />
        <img
          src={visual.sprite}
          className="player-card__sprite"
          alt={archetype.name}
        />
      </div>

      <div className="player-card__footer">
        <div className="player-card__name">{archetype.name}</div>
        <div className="player-card__gems">
          {gems.map((key, i) =>
            key ? <Gem key={i} gemKey={key} size={gemSize} /> : null
          )}
        </div>
      </div>
    </div>
  );
};

export default PlayerCard;
