import BasesBug from '../BasesBug/BasesBug';
import TierBadge from '../TierBadge/TierBadge';
import PipGroup from './PipGroup';
import ProgressBar from './ProgressBar';
import './ScoreBoard.css';

interface Props {
  balls: number;
  strikes: number;
  outs: number;
  inning: number;
  bases: boolean[];
  score: number;
  pitcherStamina: number;
  maxPitcherStamina: number;
  bossName: string;
  bossTier: 1 | 2 | 3;
  maxInnings: number;
  targetRuns: number;
}

const ScoreBoard = (props: Props) => {
  const runProgress = Math.min(props.score / props.targetRuns, 1);
  const staminaProgress = Math.min(props.pitcherStamina / props.maxPitcherStamina, 1);

  return (
    <div className="scoreBug">
      <div className="scoreBug-header">
        <span className="boss-name">{props.bossName}</span>
        <TierBadge tier={props.bossTier} />
      </div>
      <div className="scoreBug-body">

        <div className="scoreBug-col scoreBug-col--score">
          <div className="score-display">
            <span className="score-current">{props.score}</span>
            <span className="score-target"> / {props.targetRuns}</span>
          </div>
          <span className="score-label">RUNS</span>
          <ProgressBar value={runProgress} variant="run" />
          <ProgressBar value={staminaProgress} variant="stamina" />
        </div>

        <div className="scoreBug-col scoreBug-col--count">
          <div className="inning-indicator">
            <span className="inning-arrow">▲</span>
            <span className="inning-text">{props.inning} / {props.maxInnings}</span>
          </div>
          <div className="pip-rows">
            <PipGroup label="B" count={props.balls}   max={3} variant="ball"   />
            <PipGroup label="S" count={props.strikes} max={2} variant="strike" />
            <PipGroup label="O" count={props.outs}    max={2} variant="out"    />
          </div>
        </div>

        <div className="scoreBug-col scoreBug-col--bases">
          <BasesBug bases={props.bases} />
        </div>

      </div>
    </div>
  );
};

export default ScoreBoard;
