import nightBg from '../../assets/backdrops/night.png';
import './RunEndScreen.css';

interface Props {
  won: boolean;
  bossName?: string;
  bossTier?: 1 | 2 | 3;
  bossesDefeated?: number;
  onPlayAgain: () => void;
  onMainMenu?: () => void;
}

const TOTAL_BOSSES = 4;

const RunEndScreen = ({ won, bossName, bossTier, bossesDefeated, onPlayAgain, onMainMenu }: Props) => {
  const defeatedCount = won ? TOTAL_BOSSES : (bossesDefeated ?? 0);

  if (won) {
    return (
      <div className="bb-screen run-end-screen">
        <div className="run-end-content">
          <div className="run-end-emoji">🎉</div>
          <h1 className="run-end-title run-end-title--win">YOU WIN!</h1>
          <p className="run-end-subtitle">RUN COMPLETE · ALL 4 BOSSES DEFEATED</p>

          <div className="run-end-progress">
            {Array.from({ length: TOTAL_BOSSES }, (_, i) => (
              <div key={i} className="run-end-circle run-end-circle--done">✓</div>
            ))}
          </div>

          <div className="run-end-actions">
            <button className="bb-btn bb-btn--primary" onClick={onPlayAgain}>Play Again</button>
            {onMainMenu && (
              <button className="bb-btn bb-btn--secondary" onClick={onMainMenu}>Main Menu</button>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="bb-screen bb-screen--dark run-end-screen">
      <img src={nightBg} className="bb-backdrop" alt="" />

      <div className="run-end-content">
        <div className="run-end-emoji">💀</div>
        <h1 className="run-end-title run-end-title--loss">GAME OVER</h1>

        {bossName && (
          <p className="run-end-fell-at">
            Eliminated by <strong>{bossName}</strong>
            {bossTier && <span className="run-end-boss-tier"> · Tier {bossTier}</span>}
          </p>
        )}

        <div className="run-end-stats-card">
          <div className="run-end-stat">
            <span className="run-end-stat__label">Bosses Beaten</span>
            <span className="run-end-stat__value">{defeatedCount} / {TOTAL_BOSSES}</span>
          </div>
          {bossName && (
            <div className="run-end-stat">
              <span className="run-end-stat__label">Fell At</span>
              <span className="run-end-stat__value">{bossName}</span>
            </div>
          )}
        </div>

        <div className="run-end-progress">
          {Array.from({ length: TOTAL_BOSSES }, (_, i) => {
            const done = i < defeatedCount;
            return (
              <div key={i} className={`run-end-circle ${done ? 'run-end-circle--done' : ''}`}>
                {done ? '✓' : i + 1}
              </div>
            );
          })}
        </div>

        <div className="run-end-actions">
          <button className="bb-btn bb-btn--danger" onClick={onPlayAgain}>Try Again</button>
          {onMainMenu && (
            <button className="bb-btn bb-btn--secondary" onClick={onMainMenu}>Main Menu</button>
          )}
        </div>
      </div>
    </div>
  );
};

export default RunEndScreen;
