import "./MenuScreen.css";
import morningBg from "../../assets/backdrops/morning.png";
import jesterSprite from "../../assets/sprites/jester.png";
import strongmanSprite from "../../assets/sprites/strongman.png";
import zenMasterSprite from "../../assets/sprites/zen_master.png";

interface Props {
  onStartRun: () => void;
  onSampleGame: () => void;
  onHelp: () => void;
}

const MINI_CARDS = [
  { sprite: jesterSprite, name: "Jester", className: "menu-mini-card--left" },
  { sprite: strongmanSprite, name: "Strongman", className: "menu-mini-card--center" },
  { sprite: zenMasterSprite, name: "Zen Master", className: "menu-mini-card--right" },
];

const MenuScreen = ({ onStartRun, onSampleGame, onHelp }: Props) => (
  <div className="bb-screen menu-screen">
    <img src={morningBg} className="bb-backdrop" alt="" />

    <div className="menu-content">
      <h1 className="menu-logo">
        Baseball<br />at Cards
      </h1>

      <div className="menu-mini-cards">
        {MINI_CARDS.map(({ sprite, name, className }) => (
          <div key={name} className={`menu-mini-card ${className}`}>
            <img src={morningBg} className="menu-mini-card__backdrop" alt="" />
            <img src={sprite} className="menu-mini-card__sprite" alt={name} />
            <div className="menu-mini-card__footer">{name}</div>
          </div>
        ))}
      </div>

      <div className="menu-actions">
        <button className="bb-btn bb-btn--primary" onClick={onStartRun}>Start Survival Run</button>
        <button className="bb-btn bb-btn--secondary" onClick={onSampleGame}>Sample Game</button>
        <button className="bb-btn bb-btn--ghost" onClick={onHelp}>How to Play</button>
      </div>

      <span className="menu-version">v0.1.0</span>
    </div>
  </div>
);

export default MenuScreen;
