import { useState } from "react";
import { CardName } from "../../types/cardName";
import { CARD_DESCRIPTIONS } from "../../data/cardDescriptions";
import { BallIcon } from "../DisplayHand/icons/BallIcon";
import { StrikeIcon } from "../DisplayHand/icons/StrikeIcon";
import { SwingIcon } from "../DisplayHand/icons/SwingIcon";
import { FoulIcon } from "../DisplayHand/icons/FoulIcon";
import { SingleIcon } from "../DisplayHand/icons/SingleIcon";
import { HomeRunIcon } from "../DisplayHand/icons/HomeRunIcon";
import { OutIcon } from "../DisplayHand/icons/OutIcon";
import { HitByPitchIcon } from "../DisplayHand/icons/HitByPitchIcon";
import { WildPitchIcon } from "../DisplayHand/icons/WildPitchIcon";
import "./HelpScreen.css";

const CARD_ICONS: Record<CardName, React.FC<{ size?: number; color?: string }>> = {
  "Ball": BallIcon,
  "Strike": StrikeIcon,
  "Swing": SwingIcon,
  "Foul": FoulIcon,
  "Single": SingleIcon,
  "Home run": HomeRunIcon,
  "Out": OutIcon,
  "Hit by pitch": HitByPitchIcon,
  "Wild pitch": WildPitchIcon,
};

const CARD_TYPE_COLORS: Record<CardName, string> = {
  "Ball": "var(--ct-ball)",
  "Strike": "var(--ct-strike)",
  "Swing": "var(--ct-swing)",
  "Single": "var(--ct-single)",
  "Home run": "var(--ct-hr)",
  "Foul": "var(--ct-foul)",
  "Wild pitch": "var(--ct-wild)",
  "Out": "var(--ct-out)",
  "Hit by pitch": "var(--ct-hbp)",
};

const CARD_ORDER: CardName[] = [
  "Ball", "Strike", "Swing",
  "Single", "Home run", "Out",
  "Foul", "Hit by pitch", "Wild pitch",
];

interface Props {
  onBack: () => void;
}

const HelpScreen = ({ onBack }: Props) => {
  const [selectedCard, setSelectedCard] = useState<CardName | null>(null);

  const handleTileClick = (card: CardName) => {
    setSelectedCard(prev => (prev === card ? null : card));
  };

  const selected = selectedCard ? {
    card: selectedCard,
    Icon: CARD_ICONS[selectedCard],
    desc: CARD_DESCRIPTIONS[selectedCard],
    color: CARD_TYPE_COLORS[selectedCard],
  } : null;

  return (
    <div className="bb-screen help-screen">
      <header className="help-header">
        <button className="bb-btn bb-btn--ghost help-back-btn" onClick={onBack}>← Back</button>
        <h2 className="help-title">HOW TO PLAY</h2>
      </header>

      <div className="help-body">
        <div className="help-grid">
          {CARD_ORDER.map((card) => {
            const Icon = CARD_ICONS[card];
            const isSelected = selectedCard === card;
            return (
              <button
                key={card}
                className={`help-tile${isSelected ? " help-tile--selected" : ""}`}
                onClick={() => handleTileClick(card)}
              >
                <div className="help-tile-icon">
                  <Icon size={36} />
                </div>
                <div className="help-tile-name">{card}</div>
              </button>
            );
          })}
        </div>

        <div
          className="help-detail"
          style={selected ? { borderColor: selected.color } : undefined}
        >
          {selected ? (
            <>
              <div className="help-detail-header">
                <selected.Icon size={52} />
                <div className="help-detail-header-text">
                  <div className="help-detail-name" style={{ color: selected.color }}>
                    {selected.card}
                  </div>
                  <div className="help-detail-short">{selected.desc.short}</div>
                </div>
              </div>
              <p className="help-detail-body">{selected.desc.detail}</p>
            </>
          ) : null}
          <div className="help-detail-footer">TAP A CARD ABOVE TO SEE ITS RULES</div>
        </div>
      </div>
    </div>
  );
};

export default HelpScreen;
