import { Boss } from '../../types/boss';
import { PlayerArchetype } from '../../types/playerArchetype';
import TierBadge from '../TierBadge/TierBadge';
import PlayerCard from '../PlayerCard/PlayerCard';
import morningBg from '../../assets/backdrops/morning.png';
import './RunStartScreen.css';

interface Props {
  roster: PlayerArchetype[];
  boss?: Boss;
  onBeginRun: () => void;
  onBack: () => void;
}

const SLOT_LABELS = ['BAT 1', 'BAT 2', 'BAT 3', 'BAT 4', 'BAT 5', 'BAT 6', 'BAT 7', 'BAT 8', 'BAT 9'];

const RunStartScreen = ({ roster, boss, onBeginRun, onBack }: Props) => (
  <div className="bb-screen run-start-screen">
    <img src={morningBg} className="bb-backdrop" alt="" />

    <div className="run-start-content">
      <div className="run-start-header">
        <span className="run-start-eyebrow">SURVIVAL RUN</span>
        <h1 className="run-start-title">STARTING<br />LINEUP</h1>
        <p className="run-start-subtitle">Your roster shapes your deck — choose wisely.</p>
      </div>

      <div className="run-start-roster">
        {roster.slice(0, 9).map((player, i) => (
          <PlayerCard
            key={i}
            archetype={player}
            slotLabel={SLOT_LABELS[i]}
            gemSize={28}
          />
        ))}
      </div>

      {boss && (
        <div className="run-start-boss">
          <div className="run-start-boss__icon">⚾</div>
          <div className="run-start-boss__body">
            <div className="run-start-boss__name">{boss.name}</div>
            <div className="run-start-boss__stats">
              Target {boss.targetRuns} runs · {boss.maxInnings} innings
            </div>
          </div>
          <TierBadge tier={boss.tier} />
        </div>
      )}

      <div className="run-start-actions">
        <button className="bb-btn bb-btn--primary" onClick={onBeginRun}>Begin Run</button>
        <button className="bb-btn bb-btn--ghost" onClick={onBack}>← Back</button>
      </div>
    </div>
  </div>
);

export default RunStartScreen;
