import { Boss } from '../../types/boss';
import TierBadge from '../TierBadge/TierBadge';
import sunsetBg from '../../assets/backdrops/sunset.png';
import './BossWinScreen.css';

interface Props {
  boss: Boss;
  bossNumber: number;
  onContinue: () => void;
}

const TOTAL_BOSSES = 4;

const BossWinScreen = ({ boss, bossNumber, onContinue }: Props) => (
  <div className="bb-screen boss-win-screen">
    <img src={sunsetBg} className="bb-backdrop" alt="" />

    <div className="boss-win-content">
      <div className="boss-win-trophy">🏆</div>

      <h1 className="boss-win-title">BOSS DEFEATED!</h1>

      <div className="boss-win-meta">
        <span className="boss-win-name">{boss.name}</span>
        <TierBadge tier={boss.tier} />
      </div>

      <p className="boss-win-summary">Keep your momentum — the next challenge awaits.</p>

      <div className="boss-win-progress">
        {Array.from({ length: TOTAL_BOSSES }, (_, i) => {
          const circleNum = i + 1;
          const done = circleNum <= bossNumber;
          return (
            <div
              key={i}
              className={`boss-win-circle ${done ? 'boss-win-circle--done' : ''}`}
            >
              {done ? '✓' : circleNum}
            </div>
          );
        })}
      </div>

      <button className="bb-btn bb-btn--primary boss-win-cta" onClick={onContinue}>
        ◆ Recruit a Player
      </button>
    </div>
  </div>
);

export default BossWinScreen;
